// Typeform on a personal access token: every operation in Typeform's API reference (Create, Responses, Webhooks).
// actions.json is generated by `bun scripts/openapi-actions.ts typeform`; a form being filled in starts automations by
// webhook (triggers.ts), new and changed forms by polling (polls/typeform.ts).
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, watch } from "./triggers";

// Accounts in Typeform's EU data centres answer on their own host: the key is pasted as eu:<token> or typeform.eu:<token>
const HOSTS: Record<string, string> = { eu: "https://api.eu.typeform.com", "typeform.eu": "https://api.typeform.eu" };
export const split = (secret: string) => {
  const m = /^(eu|typeform\.eu):(.+)$/i.exec(secret.trim());
  return m ? { host: HOSTS[m[1]!.toLowerCase()], token: m[2]!.trim() } : { host: undefined, token: secret.trim() };
};

export const api: Api = {
  name: "Typeform",
  base: "https://api.typeform.com",
  tokenHelp: "Typeform → your account → Personal tokens",
  auth: (secret) => ({ Authorization: `Bearer ${split(secret).token}` }),
  url: (secret, base, path) => `${split(secret).host ?? base}${path}`,
};

const ME = { method: "GET", path: "/me", query: [], headers: [] };

export const typeform: OwnApp = {
  app: "typeform",
  name: "Typeform",
  logo: "/logos/typeform.svg",
  keyField: {
    label: "Personal access token",
    help: "In Typeform, open your account menu → Account → Personal tokens (admin.typeform.com/user/tokens), click Generate a new token, name it Emplio, tick every permission (Emplio can then do whatever your account can) and copy the token, which starts with tfp_. Account in Typeform's EU data centre? Pick it.",
    placeholder: "tfp_...",
    sep: ":",
    parts: [{label:"Data centre",optional:true,options:[{value:"",label:"US (most accounts)"},{value:"eu",label:"EU"},{value:"typeform.eu",label:"EU (newer, typeform.eu)"}]},{label:"Personal access token",secret:true,placeholder:"tfp_..."}],
  },
  async check(secret) {
    if (!split(secret).token) throw new AppsError("paste your Typeform personal access token");
    const me = (await call(api, secret, ME, {})) as { alias?: string; email?: string };
    return me.alias || me.email || "Typeform";
  },
  push: {
    events,
    triggers,
    start: (secret, connection, event, config) => watch(api, secret, connection, event, config),
    stop: (secret, id) => unwatch(api, secret, id),
    receive: (delivery) => receive(delivery),
  },
  actions: {
    ...(await specActions(new URL("./actions.json", import.meta.url), api)),
    upload_video: {
      description: "Upload a video to a question of a Typeform form, in one go: creates the upload (create_video_upload), sends the file, and starts making its downloadable copy. Answers the video's id.",
      input: z.object({
        file: z.any().describe('The video from the computer: {"file": "/work/clip.mp4"}'),
        form_id: z.string().describe("The form's id, as in its link (https://mysite.typeform.com/to/u6nXL7 → u6nXL7)"),
        field_id: z.string().describe("The question it's for: its id, from get_form (fields[].id)"),
        language: z.string().optional().describe("The video's spoken language as a two-letter code, like en, for captions"),
      }),
      async run(i: { file: AppFile; form_id: string; field_id: string; language?: string }, secret: string) {
        if (!(i.file instanceof AppFile)) throw new AppsError('file: give the video as {"file": "/work/clip.mp4"}');
        const send = { method: "POST", path: "/media/videos", query: [], headers: [], body: { kind: "fields" as const, fields: [["form_id", "form_id"], ["field_id", "field_id"], ["language", "language"]] as [string, string][] } };
        const made = (await call(api, secret, send, i)) as { id: string; upload_url: string };
        const res = await fetch(made.upload_url, { method: "PUT", headers: { "Content-Type": i.file.mimetype }, body: i.file.bytes as Uint8Array<ArrayBuffer> });
        if (!res.ok) throw new AppsError(`Typeform: the video didn't upload (${res.status})`);
        await call(api, secret, { method: "POST", path: "/media/videos/{id}/master", query: [], headers: [] }, { id: made.id });
        return { id: made.id };
      },
    },
  },
};
